/** Widths generated for product images by scripts/process-images.mjs. */
export const productImageWidths = [400, 800, 1200] as const;

/** Transparent product cutouts generated by scripts/process-images.mjs, by height. */
export function cutout(slug: string): { src: string; srcSet: string } {
  const base = `/images/cutouts/${slug}`;
  return { src: `${base}-480.webp`, srcSet: `${base}-480.webp 1x, ${base}-960.webp 2x` };
}

export function srcSet(base: string, widths: readonly number[], ext = 'webp'): string {
  return widths.map((w) => `${base}-${w}.${ext} ${w}w`).join(', ');
}
